-- 001: main table, one row per earthquake event.
-- Loaded by load.py from the rows built by transform_record (see transform.py).
--
-- Not here yet: the business key / UNIQUE constraint used by MERGE (decision pending,
-- see DECISIONS.md "Business key"). It will be added in a later file, e.g. 003.

CREATE TABLE IF NOT EXISTS earthquakes (
    -- Surrogate key generated by the database (decision no. 9); the pipeline never sets it.
    id                BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Required fields (validate_record rejects records without them).
    event_time_utc    TIMESTAMPTZ   NOT NULL,   -- when the earthquake happened, stored in UTC
    latitude          NUMERIC(8,5)  NOT NULL,   -- decimal degrees, negative = south
    longitude         NUMERIC(8,5)  NOT NULL,   -- decimal degrees
    magnitude         NUMERIC(4,2)  NOT NULL,
    depth_km          NUMERIC(6,2)  NOT NULL,

    -- Optional fields: NULL when BMKG sends nothing (transform turns blank text into None).
    region            TEXT,                     -- BMKG "Wilayah"
    tsunami_potential TEXT,                     -- BMKG "Potensi"

    -- Lineage: where and when this row came from.
    source_feed       TEXT          NOT NULL,   -- autogempa, gempaterkini or gempadirasakan
    ingested_at       TIMESTAMPTZ   NOT NULL    -- when the pipeline run fetched it (UTC)
);
